import { z } from 'zod';
import type { IntegrationsClient } from '../IntegrationsClient';
import { CosmosPageSchema } from '../../types/cosmos';
import { CosmosProfilePageSchema } from '../../types/cosmos-profile';
import {
  ReferenceCatalogPageSchema,
  referenceProvider,
  type ReferenceCollection,
  type ReferenceProfile,
  type ReferenceDiscoveryRequest,
} from '../../types/reference-connectors';
import { ReferenceContentsPageSchema } from '../../types/reference-pages';
import { ProviderRateLimit } from '../../utils/ProviderRateLimit';
import { cosmosPage, cosmosRequest } from './cosmosPage';

export type ReferenceConnectorClient = Pick<
  IntegrationsClient,
  | 'discoverReferenceCollections'
  | 'readReferenceCollection'
  | 'referenceAccount'
>;
interface ReferenceReaderOptions {
  cosmos: Pick<IntegrationsClient, 'discoverCosmos' | 'fetchCosmos'>;
  connectors?: ReferenceConnectorClient;
}
const CosmosTraversalPageSchema = ReferenceContentsPageSchema.extend({
  nextCursor: z.string().min(1).nullable(),
});
export class ReferenceReader {
  constructor(private readonly options: ReferenceReaderOptions) {}

  async discover({
    request,
    cursor,
    expectedAccountId,
    signal,
  }: {
    request: ReferenceDiscoveryRequest;
    cursor?: string;
    expectedAccountId?: string;
    signal: AbortSignal;
  }) {
    if ('url' in request)
      return CosmosProfilePageSchema.parse(
        await this.options.cosmos.discoverCosmos({
          url: request.url,
          cursor,
          signal,
        }),
      );
    const page = ReferenceCatalogPageSchema.parse(
      await this.connectors().discoverReferenceCollections({
        ...request,
        cursor,
        expectedAccountId,
        signal,
      }),
    );
    if (referenceProvider(page.profile) !== request.provider)
      throw new Error('Reference provider identity changed during discovery');
    return page;
  }

  async verify(profile: ReferenceProfile, signal: AbortSignal) {
    const provider = referenceProvider(profile);
    if (provider === 'cosmos') return;
    const account = await this.connectors().referenceAccount({
      provider,
      expectedAccountId: profile.id,
      signal,
    });
    if (account.id !== profile.id || referenceProvider(account) !== provider)
      throw new Error('Reference account changed; discover the account again');
  }

  async read({
    profile,
    collection,
    cursor,
    signal,
  }: {
    profile: ReferenceProfile;
    collection: ReferenceCollection;
    cursor: string | null;
    signal: AbortSignal;
  }) {
    const provider = referenceProvider(profile);
    if (provider !== 'cosmos') {
      const page = ReferenceContentsPageSchema.parse(
        await this.connectors().readReferenceCollection({
          provider,
          expectedAccountId: profile.id,
          collectionId: collection.id,
          cursor: cursor ?? undefined,
          signal,
        }),
      );
      if (
        page.accountId !== profile.id ||
        page.collectionId !== collection.id ||
        page.isCollectionComplete !== (page.nextCursor === null)
      )
        throw new Error(
          'Reference account, collection, or pagination changed during planning',
        );
      return page;
    }
    if (!collection.url) throw new Error('Cosmos collection URL is required');
    const request = { collectionId: collection.id, ...cosmosRequest(cursor) };
    const result = await this.options.cosmos.fetchCosmos({
      url: collection.url,
      ...request,
      signal,
    });
    if (result.status === 'error') {
      if (result.reason === 'rate_limited')
        throw new ProviderRateLimit(result.retryAfterMs);
      throw new Error(result.message);
    }
    const data = CosmosPageSchema.parse(result);
    if (data.collection.id !== request.collectionId)
      throw new Error('Cosmos collection identity changed during planning');
    const page = cosmosPage(data, cursor);
    return CosmosTraversalPageSchema.parse({
      accountId: profile.id,
      collectionId: data.collection.id,
      references: page.references,
      total: data.total,
      nextCursor: page.cursor,
      isCollectionComplete: data.nextCursor === null,
    });
  }

  private connectors() {
    if (!this.options.connectors)
      throw new Error('Authenticated reference discovery is unavailable');
    return this.options.connectors;
  }
}
